for (size_t i = 0; i < P1.size(); ++i) {
    for (size_t j = 0; j < P2.size(); ++j) {
        cg3::Point2d p1 = P1[i];
        cg3::Point2d p2 = P1[(i + 1) % P1.size()];
        cg3::Point2d p3 = P2[j];
        cg3::Point2d p4 = P2[(j + 1) % P2.size()];

        double d1 = p3.perpendicularDot(p2 - p1);
        double d2 = p4.perpendicularDot(p2 - p1);
        double d3 = p1.perpendicularDot(p4 - p3);
        double d4 = p2.perpendicularDot(p4 - p3);

        if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
            ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
            return true;
        }

        // Check if any point of P1 lies on any edge of P2
        if (d1 == 0 && std::min(p3.x(), p4.x()) <= p1.x() && p1.x() <= std::max(p3.x(), p4.x()) &&
            std::min(p3.y(), p4.y()) <= p1.y() && p1.y() <= std::max(p3.y(), p4.y())) {
            return true;
        }
        if (d2 == 0 && std::min(p3.x(), p4.x()) <= p2.x() && p2.x() <= std::max(p3.x(), p4.x()) &&
            std::min(p3.y(), p4.y()) <= p2.y() && p2.y() <= std::max(p3.y(), p4.y())) {
            return true;
        }
        if (d3 == 0 && std::min(p1.x(), p2.x()) <= p3.x() && p3.x() <= std::max(p1.x(), p2.x()) &&
            std::min(p1.y(), p2.y()) <= p3.y() && p3.y() <= std::max(p1.y(), p2.y())) {
            return true;
        }
        if (d4 == 0 && std::min(p1.x(), p2.x()) <= p4.x() && p4.x() <= std::max(p1.x(), p2.x()) &&
            std::min(p1.y(), p2.y()) <= p4.y() && p4.y() <= std::max(p1.y(), p2.y())) {
            return true;
        }
    }
}

// Check if one polygon is completely inside the other
bool p1InsideP2 = false;
bool p2InsideP1 = false;

if (P1.size() > 0) {
    cg3::Point2d testPoint = P1[0];
    int crossings = 0;
    for (size_t j = 0; j < P2.size(); ++j) {
        cg3::Point2d p3 = P2[j];
        cg3::Point2d p4 = P2[(j + 1) % P2.size()];

        if ((p3.y() <= testPoint.y() && p4.y() > testPoint.y()) ||
            (p4.y() <= testPoint.y() && p3.y() > testPoint.y())) {
            double vt = (testPoint.y() - p3.y()) / (p4.y() - p3.y());
            if (testPoint.x() < p3.x() + vt * (p4.x() - p3.x())) {
                crossings++;
            }
        }
    }
    p1InsideP2 = (crossings % 2 == 1);
}

if (P2.size() > 0) {
    cg3::Point2d testPoint = P2[0];
    int crossings = 0;
    for (size_t i = 0; i < P1.size(); ++i) {
        cg3::Point2d p1 = P1[i];
        cg3::Point2d p2 = P1[(i + 1) % P1.size()];

        if ((p1.y() <= testPoint.y() && p2.y() > testPoint.y()) ||
            (p2.y() <= testPoint.y() && p1.y() > testPoint.y())) {
            double vt = (testPoint.y() - p1.y()) / (p2.y() - p1.y());
            if (testPoint.x() < p1.x() + vt * (p2.x() - p1.x())) {
                crossings++;
            }
        }
    }
    p2InsideP1 = (crossings % 2 == 1);
}

if (p1InsideP2 || p2InsideP1) {
    return true;
}

return false;

